"use client";

import {
  formatLlpin,
  type TinResult,
  validateDin,
  validateFcra,
  validateIec,
  validateLlpin,
  validateRera,
  validateTin,
} from "../../lib/corporate-ids";
import type { IdResult } from "../../lib/gov-ids";
import type { PanResult } from "../../lib/pan";
import { IdentifierInput, type IdentifierInputProps } from "./identifier-input";

type WrapperProps<T extends { valid: boolean; error?: { message: string } }> =
  Omit<IdentifierInputProps<T>, "validate" | "transform" | "badge">;

const digits = (max: number) => (raw: string) =>
  raw.replace(/\D/g, "").slice(0, max);
const alnum = (max: number) => (raw: string) =>
  raw
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, max);

/** DIN — Director Identification Number, 8 digits. */
export function DINInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="01234567"
      tracking="tracking-[0.18em]"
      {...props}
      validate={validateDin}
      transform={digits(8)}
    />
  );
}

/** LLPIN — three letters then four digits, hyphenated as you type. */
export function LLPINInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="AAB-1234"
      tracking="tracking-[0.16em]"
      {...props}
      validate={validateLlpin}
      transform={formatLlpin}
    />
  );
}

/** FCRA registration — 9 digits, required for foreign donations. */
export function FCRAInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="123456789"
      tracking="tracking-[0.18em]"
      {...props}
      validate={validateFcra}
      transform={digits(9)}
    />
  );
}

/**
 * IEC — since 2021 an entity's Import Export Code *is* its PAN, so this
 * validates PAN structure. Regexes written before that change still expect a
 * 10-digit number and reject every modern IEC.
 */
export function IECInput(props: WrapperProps<PanResult>) {
  return (
    <IdentifierInput<PanResult>
      placeholder="ABCPE1234F"
      tracking="tracking-[0.12em]"
      {...props}
      validate={validateIec}
      transform={alnum(10)}
      badge={(result) => result.holderType}
    />
  );
}

/** RERA — per-state formats, so validation is deliberately permissive. */
export function RERAInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="PRM/KA/RERA/1251/446/PR/123456"
      tracking="tracking-[0.02em]"
      {...props}
      validate={validateRera}
      transform={(raw) =>
        raw
          .toUpperCase()
          .replace(/[^A-Z0-9/-]/g, "")
          .slice(0, 40)
      }
    />
  );
}

/** TIN — the pre-GST taxpayer number, still found on historical invoices. */
export function TINInput(props: WrapperProps<TinResult>) {
  return (
    <IdentifierInput<TinResult>
      placeholder="29123456789"
      tracking="tracking-[0.14em]"
      {...props}
      validate={validateTin}
      transform={digits(11)}
    />
  );
}

export type DINInputProps = WrapperProps<IdResult>;
export type LLPINInputProps = WrapperProps<IdResult>;
export type FCRAInputProps = WrapperProps<IdResult>;
export type IECInputProps = WrapperProps<PanResult>;
export type RERAInputProps = WrapperProps<IdResult>;
export type TINInputProps = WrapperProps<TinResult>;

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

"use client";

import * as React from "react";

import {
  cn,
  controlClasses,
  Field,
  FieldBadge,
  useFieldState,
  type ValidationLike,
} from "./field";

export interface IdentifierInputProps<T extends ValidationLike>
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validateOn?: "blur" | "change";
  validate: (raw: string) => T;
  /** Input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  /** Derives the right-hand badge from a valid result. */
  badge?: (result: T) => string | undefined;
  label?: string;
  description?: string;
  containerClassName?: string;
  /** Extra letter-spacing suits fixed-format identifiers. */
  tracking?: string;
}

/**
 * The shared body of every fixed-format identifier field. The specific
 * components (PAN, TAN, CIN, …) are thin wrappers that supply a validator, a
 * mask and a placeholder — everything else behaves identically by construction.
 */
export function IdentifierInput<T extends ValidationLike>({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  validate,
  transform,
  badge,
  label,
  description,
  className,
  containerClassName,
  tracking = "tracking-[0.12em]",
  id,
  onBlur,
  ...props
}: IdentifierInputProps<T>) {
  const reactId = React.useId();
  const inputId = id ?? `id-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<T>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn,
  });

  const badgeText =
    badge && field.result.valid ? badge(field.result) : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          autoComplete="off"
          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            tracking,
            badgeText && "pr-36",
            className,
          )}
        />
        {badgeText && <FieldBadge>{badgeText}</FieldBadge>}
      </div>
    </Field>
  );
}

/**
 * Corporate registration and compliance identifiers.
 *
 * All structural — none of these publish a check digit. IEC is the interesting
 * one: since 2021 the DGFT stopped issuing separate codes and an entity's IEC
 * simply *is* its PAN, so we reuse the PAN validator rather than duplicating it.
 */

import type { IdResult } from "./gov-ids";
import { type PanResult, validatePan } from "./pan";

function bad<E extends string>(
  code: E,
  message: string,
  normalized: string,
): IdResult<E> {
  return { valid: false, normalized, error: { code, message } };
}

const upper = (input: string) => input.replace(/[\s-]/g, "").toUpperCase();

/* ── DIN ─────────────────────────────────────────────────────────────────── */

export type DinErrorCode = "empty" | "not_digits" | "wrong_length";

/** Director Identification Number — 8 digits, one per person for life. */
export function validateDin(input: string): IdResult<DinErrorCode> {
  const din = input.replace(/\D/g, "");
  if (!input.trim()) return bad("empty", "Enter a DIN.", din);
  if (/[^\d\s-]/.test(input))
    return bad("not_digits", "A DIN is digits only.", din);
  if (din.length !== 8) {
    return bad(
      "wrong_length",
      `A DIN is 8 digits — ${din.length} so far.`,
      din,
    );
  }
  return { valid: true, normalized: din };
}

/* ── LLPIN ───────────────────────────────────────────────────────────────── */

const LLPIN_RE = /^[A-Z]{3}[0-9]{4}$/;

export type LlpinErrorCode = "empty" | "wrong_length" | "bad_shape";

/** LLP Identification Number — three letters then four digits, e.g. AAB-1234. */
export function validateLlpin(input: string): IdResult<LlpinErrorCode> {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter an LLPIN.", id);
  if (id.length !== 7) {
    return bad(
      "wrong_length",
      `An LLPIN is 7 characters — ${id.length} so far.`,
      id,
    );
  }
  if (!LLPIN_RE.test(id)) {
    return bad(
      "bad_shape",
      "An LLPIN looks like AAB-1234 — three letters, four digits.",
      id,
    );
  }
  return { valid: true, normalized: id };
}

/** Re-insert the hyphen LLPINs are printed with. */
export function formatLlpin(input: string): string {
  const id = upper(input).slice(0, 7);
  return id.length > 3 ? `${id.slice(0, 3)}-${id.slice(3)}` : id;
}

/* ── FCRA ────────────────────────────────────────────────────────────────── */

export type FcraErrorCode = "empty" | "not_digits" | "wrong_length";

/**
 * FCRA registration — 9 digits. Required of any NGO receiving foreign
 * contributions, and checked constantly in donation flows.
 */
export function validateFcra(input: string): IdResult<FcraErrorCode> {
  const id = input.replace(/\D/g, "");
  if (!input.trim())
    return bad("empty", "Enter an FCRA registration number.", id);
  if (/[^\d\s-]/.test(input))
    return bad("not_digits", "An FCRA number is digits only.", id);
  if (id.length !== 9) {
    return bad(
      "wrong_length",
      `An FCRA number is 9 digits — ${id.length} so far.`,
      id,
    );
  }
  return { valid: true, normalized: id };
}

/* ── IEC ─────────────────────────────────────────────────────────────────── */

export type IecErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "bad_holder_type";

/**
 * Import Export Code. Since 2021 the DGFT issues no separate code — an
 * entity's IEC is its PAN. So this is the PAN validator with IEC wording,
 * which is exactly the sort of thing a hand-rolled regex gets wrong by
 * still expecting the old 10-digit numeric format.
 */
export function validateIec(input: string): PanResult {
  const result = validatePan(input);
  if (result.valid || !result.error) return result;

  return {
    ...result,
    error: {
      code: result.error.code,
      message: result.error.message.replace(/\bPAN\b/g, "IEC"),
    },
  };
}

/* ── RERA ────────────────────────────────────────────────────────────────── */

export type ReraErrorCode = "empty" | "too_short" | "too_long" | "bad_shape";

/**
 * RERA registration numbers are issued per state authority and share no
 * national format — Maharashtra's differ from Karnataka's in both length and
 * alphabet. We accept 8–30 alphanumerics (slashes and hyphens stripped) and
 * don't pretend to more precision than exists.
 */
export function validateRera(input: string): IdResult<ReraErrorCode> {
  const id = input.replace(/[\s\-/]/g, "").toUpperCase();
  if (!input.trim())
    return bad("empty", "Enter a RERA registration number.", id);
  if (!/^[0-9A-Z]+$/.test(id)) {
    return bad("bad_shape", "A RERA number is letters and digits only.", id);
  }
  if (id.length < 8)
    return bad("too_short", "That looks too short for a RERA number.", id);
  if (id.length > 30)
    return bad("too_long", "That looks too long for a RERA number.", id);
  return { valid: true, normalized: id };
}

/* ── TIN (legacy VAT / CST) ──────────────────────────────────────────────── */

export type TinErrorCode =
  | "empty"
  | "not_digits"
  | "wrong_length"
  | "unknown_state";

export interface TinResult extends IdResult<TinErrorCode> {
  stateCode?: string;
}

/**
 * Taxpayer Identification Number — 11 digits, first two being the state code.
 * Superseded by GSTIN in 2017, but still turns up on historical invoices and
 * in ledger migrations, which is the only reason to support it.
 */
export function validateTin(input: string): TinResult {
  const tin = input.replace(/\D/g, "");
  if (!input.trim()) return bad("empty", "Enter a TIN.", tin);
  if (/[^\d\s-]/.test(input))
    return bad("not_digits", "A TIN is digits only.", tin);
  if (tin.length !== 11) {
    return bad(
      "wrong_length",
      `A TIN is 11 digits — ${tin.length} so far.`,
      tin,
    );
  }

  const stateCode = tin.slice(0, 2);
  if (Number(stateCode) < 1 || Number(stateCode) > 38) {
    return bad(
      "unknown_state",
      `“${stateCode}” isn't a valid state code.`,
      tin,
    );
  }
  return { valid: true, normalized: tin, stateCode };
}

/**
 * Government photo-ID identifiers used in Indian KYC: Voter ID (EPIC),
 * driving licence, and passport.
 *
 * None of these carry a public checksum, so everything here is structural.
 * Real verification means the issuing authority's API — ECI, Parivahan/Sarathi,
 * or the Passport Seva portal respectively.
 */

import { RTO_STATE_CODES } from "./vehicle";

export interface IdResult<E extends string = string> {
  valid: boolean;
  normalized: string;
  error?: { code: E; message: string };
}

function ok<E extends string>(normalized: string): IdResult<E> {
  return { valid: true, normalized };
}

function bad<E extends string>(
  code: E,
  message: string,
  normalized: string,
): IdResult<E> {
  return { valid: false, normalized, error: { code, message } };
}

const upper = (input: string) => input.replace(/[\s-]/g, "").toUpperCase();

/* ── Voter ID (EPIC) ─────────────────────────────────────────────────────── */

const EPIC_RE = /^[A-Z]{3}[0-9]{7}$/;

export type VoterIdErrorCode = "empty" | "wrong_length" | "bad_shape";

/**
 * EPIC numbers are three letters (the Functional Constituency code) followed by
 * seven digits. Older cards used other shapes, but every card issued since the
 * 2000s follows this one.
 */
export function validateVoterId(input: string): IdResult<VoterIdErrorCode> {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter a Voter ID number.", id);
  if (id.length !== 10) {
    return bad(
      "wrong_length",
      `An EPIC number is 10 characters — ${id.length} so far.`,
      id,
    );
  }
  if (!EPIC_RE.test(id)) {
    return bad(
      "bad_shape",
      "A Voter ID looks like ABC1234567 — three letters, seven digits.",
      id,
    );
  }
  return ok(id);
}

/* ── Driving licence ─────────────────────────────────────────────────────── */

const DL_RE = /^([A-Z]{2})(\d{2})(\d{4})(\d{7})$/;

export type LicenceErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "unknown_state"
  | "bad_year";

export interface LicenceResult extends IdResult<LicenceErrorCode> {
  stateCode?: string;
  state?: string;
  rtoCode?: string;
  year?: number;
}

/**
 * Format is `SSRRYYYYNNNNNNN` — state, RTO office, year of issue, serial.
 * Printed with spaces or hyphens in practice, so we strip them first.
 */
export function validateDrivingLicence(input: string): LicenceResult {
  const dl = upper(input);
  if (!input.trim()) return bad("empty", "Enter a driving licence number.", dl);
  if (dl.length !== 15) {
    return bad(
      "wrong_length",
      `A licence number is 15 characters — ${dl.length} so far.`,
      dl,
    );
  }

  const match = DL_RE.exec(dl);
  if (!match) {
    return bad(
      "bad_shape",
      "A licence looks like MH1220110012345 — state, RTO, year, serial.",
      dl,
    );
  }

  const [, stateCode, rtoCode, yearStr] = match;
  const state = RTO_STATE_CODES[stateCode];
  if (!state)
    return bad(
      "unknown_state",
      `“${stateCode}” isn't a state code we recognise.`,
      dl,
    );

  const year = Number(yearStr);
  const thisYear = new Date().getFullYear();
  if (year < 1950 || year > thisYear) {
    return bad("bad_year", `“${yearStr}” isn't a plausible year of issue.`, dl);
  }

  return { valid: true, normalized: dl, stateCode, state, rtoCode, year };
}

/* ── Passport ────────────────────────────────────────────────────────────── */

const PASSPORT_RE = /^[A-PR-WY][0-9]{7}$/;

export type PassportErrorCode = "empty" | "wrong_length" | "bad_shape";

/**
 * Indian passports are one letter then seven digits. The letters Q, X and Z are
 * not used as the leading character, which is a cheap extra typo check.
 */
export function validatePassport(input: string): IdResult<PassportErrorCode> {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter a passport number.", id);
  if (id.length !== 8) {
    return bad(
      "wrong_length",
      `A passport number is 8 characters — ${id.length} so far.`,
      id,
    );
  }
  if (!PASSPORT_RE.test(id)) {
    return bad(
      "bad_shape",
      "A passport number looks like A1234567 — one letter, seven digits.",
      id,
    );
  }
  return ok(id);
}

/**
 * PAN (Permanent Account Number) validation.
 *
 * Format is `AAAAA9999A` — five letters, four digits, one letter.
 *
 * The two letters worth understanding:
 *   - 4th character encodes the holder type (P = individual, C = company, …).
 *   - 5th character is the first letter of the surname for an individual, or of
 *     the entity name otherwise.
 *
 * The 10th character *is* a check digit, but the Income Tax Department has
 * never published the algorithm. Anyone claiming to verify a PAN checksum
 * offline is guessing. We validate structure only and say so — real
 * verification needs the NSDL/Protean or Income Tax verification API.
 */

const PAN_RE = /^[A-Z]{5}[0-9]{4}[A-Z]$/;

export type PanHolderType =
  | "Individual"
  | "Company"
  | "Hindu Undivided Family"
  | "Association of Persons"
  | "Body of Individuals"
  | "Government"
  | "Artificial Juridical Person"
  | "Local Authority"
  | "Firm / LLP"
  | "Trust";

const HOLDER_TYPES: Readonly<Record<string, PanHolderType>> = {
  P: "Individual",
  C: "Company",
  H: "Hindu Undivided Family",
  A: "Association of Persons",
  B: "Body of Individuals",
  G: "Government",
  J: "Artificial Juridical Person",
  L: "Local Authority",
  F: "Firm / LLP",
  T: "Trust",
};

export type PanErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "bad_holder_type";

export interface PanResult {
  valid: boolean;
  /** Uppercased, whitespace stripped. */
  normalized: string;
  /** Decoded from the 4th character, when recognised. */
  holderType?: PanHolderType;
  /** First letter of the surname / entity name (5th character). */
  nameInitial?: string;
  error?: { code: PanErrorCode; message: string };
}

function fail(
  code: PanErrorCode,
  message: string,
  normalized: string,
): PanResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizePan(input: string): string {
  return input.replace(/\s/g, "").toUpperCase();
}

export function validatePan(input: string): PanResult {
  const pan = normalizePan(input);

  if (!input.trim()) return fail("empty", "Enter a PAN.", pan);
  if (pan.length !== 10) {
    return fail(
      "wrong_length",
      `A PAN is 10 characters — ${pan.length} so far.`,
      pan,
    );
  }
  if (!PAN_RE.test(pan)) {
    return fail(
      "bad_shape",
      "A PAN looks like ABCDE1234F — five letters, four digits, one letter.",
      pan,
    );
  }

  const holderType = HOLDER_TYPES[pan[3]];
  if (!holderType) {
    return fail(
      "bad_holder_type",
      `“${pan[3]}” isn't a valid 4th character — it encodes the holder type.`,
      pan,
    );
  }

  return { valid: true, normalized: pan, holderType, nameInitial: pan[4] };
}

/** Just the holder type for a 4th character, if you need it standalone. */
export function panHolderType(char: string): PanHolderType | undefined {
  return HOLDER_TYPES[char.toUpperCase()];
}

/** `ABCDE1234F` → `ABCXXXXX4F`. For display and logs. */
export function maskPan(input: string): string {
  const pan = normalizePan(input);
  if (pan.length !== 10) return pan.replace(/./g, "X");
  return `${pan.slice(0, 3)}XXXXX${pan.slice(8)}`;
}

/**
 * Indian vehicle registration number validation.
 *
 * Two live formats:
 *
 *   State series   MH 12 AB 1234   state + RTO district + series + number
 *   Bharat (BH)    22 BH 1234 AA   year + "BH" + number + series
 *
 * The BH series was introduced in 2021 for vehicles that move between states,
 * and its digits-first shape breaks any regex written only for the classic
 * format — which is why plenty of Indian insurance forms still reject it.
 */

const STATE_SERIES_RE = /^([A-Z]{2})(\d{1,2})([A-Z]{1,3})(\d{1,4})$/;
const BH_SERIES_RE = /^(\d{2})(BH)(\d{4})([A-Z]{1,2})$/;

export const RTO_STATE_CODES: Readonly<Record<string, string>> = {
  AP: "Andhra Pradesh",
  AR: "Arunachal Pradesh",
  AS: "Assam",
  BR: "Bihar",
  CG: "Chhattisgarh",
  CH: "Chandigarh",
  DD: "Daman & Diu",
  DL: "Delhi",
  DN: "Dadra & Nagar Haveli",
  GA: "Goa",
  GJ: "Gujarat",
  HP: "Himachal Pradesh",
  HR: "Haryana",
  JH: "Jharkhand",
  JK: "Jammu & Kashmir",
  KA: "Karnataka",
  KL: "Kerala",
  LA: "Ladakh",
  LD: "Lakshadweep",
  MH: "Maharashtra",
  ML: "Meghalaya",
  MN: "Manipur",
  MP: "Madhya Pradesh",
  MZ: "Mizoram",
  NL: "Nagaland",
  OD: "Odisha",
  OR: "Odisha (old code)",
  PB: "Punjab",
  PY: "Puducherry",
  RJ: "Rajasthan",
  SK: "Sikkim",
  TN: "Tamil Nadu",
  TR: "Tripura",
  TS: "Telangana",
  UK: "Uttarakhand",
  UA: "Uttarakhand (old code)",
  UP: "Uttar Pradesh",
  WB: "West Bengal",
  AN: "Andaman & Nicobar Islands",
};

export type VehicleFormat = "state" | "bharat";

export type VehicleErrorCode =
  | "empty"
  | "too_short"
  | "bad_shape"
  | "unknown_state";

export interface VehicleResult {
  valid: boolean;
  normalized: string;
  format?: VehicleFormat;
  stateCode?: string;
  state?: string;
  /** RTO district number — state format only. */
  districtCode?: string;
  series?: string;
  number?: string;
  /** Registration year — BH series only. */
  year?: string;
  formatted?: string;
  error?: { code: VehicleErrorCode; message: string };
}

function fail(
  code: VehicleErrorCode,
  message: string,
  normalized: string,
): VehicleResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizeVehicleNumber(input: string): string {
  return input.replace(/[\s-]/g, "").toUpperCase();
}

export function validateVehicleNumber(input: string): VehicleResult {
  const reg = normalizeVehicleNumber(input);

  if (!input.trim()) return fail("empty", "Enter a registration number.", reg);
  if (reg.length < 6) {
    return fail(
      "too_short",
      "That's too short for a registration number.",
      reg,
    );
  }

  const bh = BH_SERIES_RE.exec(reg);
  if (bh) {
    const [, year, , number, series] = bh;
    return {
      valid: true,
      normalized: reg,
      format: "bharat",
      year: `20${year}`,
      number,
      series,
      formatted: `${year} BH ${number} ${series}`,
    };
  }

  const state = STATE_SERIES_RE.exec(reg);
  if (!state) {
    return fail(
      "bad_shape",
      "Use MH12AB1234, or 22BH1234AA for a Bharat series plate.",
      reg,
    );
  }

  const [, stateCode, districtCode, series, number] = state;
  const stateName = RTO_STATE_CODES[stateCode];
  if (!stateName) {
    return fail(
      "unknown_state",
      `“${stateCode}” isn't a state code we recognise.`,
      reg,
    );
  }

  return {
    valid: true,
    normalized: reg,
    format: "state",
    stateCode,
    state: stateName,
    districtCode,
    series,
    number,
    formatted: `${stateCode} ${districtCode} ${series} ${number}`,
  };
}
